insert into public.cities (id, name_ja, name_en, lat, lng, intro_ja, intro_en, guide_notes, pano_id, active, sort) values
('tokyo-shibuya','東京・渋谷','Tokyo · Shibuya',35.65907020237839,139.7004739629136,'渋谷へようこそ。ここは駅前で、スクランブル交差点はすぐそばです。','Welcome to Shibuya. You are in front of the station, right by the famous scramble crossing.','Shibuya Scramble Crossing, Hachiko statue, Shibuya Sky observation deck, shopping and nightlife, Meiji Shrine and Yoyogi Park are a walk or short train ride away. The station is a large, confusing complex.','C4Fb1Jo2Gc10WBB3W5_clQ',true,10),
('tokyo-asakusa','東京・浅草','Tokyo · Asakusa',35.7105738555828,139.7961864989535,'浅草へようこそ。雷門の近くです。仲見世通りを抜けると浅草寺に着きます。','Welcome to Asakusa. You are near Kaminarimon gate. Walk down Nakamise street to reach Senso-ji temple.','Kaminarimon, Nakamise shopping street, Senso-ji temple, Sumida River and Tokyo Skytree views, traditional snacks and rickshaw rides. Crowded in the daytime; calmer early morning and evening.','bMrp7vpiNBWiu2zk8MxwMg',true,20),
('tokyo-shinjuku','東京・新宿 歌舞伎町','Tokyo · Shinjuku Kabukicho',35.69419920827744,139.7032366469576,'新宿の歌舞伎町のあたりへようこそ。飲食店やネオンの看板が並ぶ、夜もにぎやかな街です。','Welcome to Kabukicho in Shinjuku. Restaurants and neon signs line the streets of this lively nightlife district.','Kabukicho nightlife, Golden Gai and Omoide Yokocho for small bars and yakitori, Shinjuku Gyoen garden, free observation decks at the Tokyo Metropolitan Government Building. Shinjuku Station is huge; allow extra time. Be careful of street touts at night in Kabukicho.','DwtausUYpqGP_dOImT2dFw',true,30),
('kamakura-komachi','神奈川・鎌倉 小町通り','Kamakura · Komachi-dori',35.32001198776832,139.5517174684008,'鎌倉の小町通りへようこそ。駅から鶴岡八幡宮の方へ続く、食べ歩きの人気の通りです。','Welcome to Komachi-dori in Kamakura, a popular snack street leading from the station toward Tsurugaoka Hachimangu shrine.','Komachi-dori street food and souvenirs, Tsurugaoka Hachimangu shrine, the Great Buddha at Kotoku-in, Enoden train and Enoshima are nearby. About an hour from Tokyo by train. Weekends are very crowded.','Si0Pg7v9DVz2hRNU54_ZPA',true,40),
('kyoto-gion','京都・祇園','Kyoto · Gion',35.0032216786772,135.7750014353892,'京都の祇園へようこそ。このあたりでは町家が並ぶ通りを歩けます。','Welcome to Gion in Kyoto. Streets here are lined with traditional machiya townhouses.','Gion district, Hanamikoji street, Yasaka Shrine, Kiyomizu-dera and Higashiyama are nearby. Be respectful of residents and of geiko and maiko; photography rules apply on private lanes. Buses are crowded; walking and trains are often better.','8Yx_sgJixW821xV2H9vbrg',true,50),
('kyoto-fushimi','京都・伏見稲荷大社周辺','Kyoto · Near Fushimi Inari Shrine',34.96757459517679,135.7723004213781,'京都の伏見稲荷の近くへようこそ。千本鳥居で知られる神社は、すぐそばです。','Welcome to the area near Fushimi Inari Shrine in Kyoto, famous for its thousands of red torii gates.','Fushimi Inari Taisha with the Senbon Torii path up Mt. Inari, fox statues, street food near the main approach. The full hike takes 2 to 3 hours; wear comfortable shoes. Open all day; early morning is quieter. Easy by train from Kyoto Station.','qVKWd1UxQZk9HUNWlEPC0w',true,60),
('osaka-dotonbori','大阪・道頓堀','Osaka · Dotonbori',34.66872487244701,135.5010233904262,'大阪の道頓堀へようこそ。看板が並び、食べ歩きの店が続くにぎやかなエリアです。','Welcome to Dotonbori in Osaka, a lively area of bright signs and street food.','Dotonbori canal, Glico sign, Ebisu Bridge, street food such as takoyaki and okonomiyaki, Namba and Shinsaibashi shopping. Very busy in the evening. Osaka Castle and Universal Studios Japan are reachable by train.','2XQNY3SSxlFwcnrxbJwDHQ',true,70),
('osaka-castle','大阪・大阪城','Osaka · Osaka Castle',34.68730367922188,135.5254540681785,'大阪城へようこそ。天守閣を中心に、広い公園になっています。','Welcome to Osaka Castle. The main keep stands in the middle of a large park.','Osaka Castle keep and museum, moats and stone walls, Osaka Castle Park, plum and cherry blossom seasons. Reachable by train from central Osaka in about 10 minutes. Large grounds; plan for a lot of walking.','0Bi781Owm_K6R2ANWYX3yg',true,80),
('nara-park','奈良・奈良公園','Nara · Nara Park',34.68509732059267,135.842646007272,'奈良公園へようこそ。鹿が自由に歩く広い公園で、東大寺や春日大社が近くにあります。','Welcome to Nara Park, a large park where deer roam freely. Todai-ji and Kasuga Taisha are nearby.','Free-roaming deer (buy deer crackers; they can nip), Todai-ji with the Great Buddha, Kasuga Taisha shrine, Kofuku-ji pagoda, Naramachi old town. About 45 minutes from Kyoto or Osaka by train. Many sights are within walking distance.','zjLqYYoxlNJyTZ_n21UNvw',true,90),
('kobe-motomachi','兵庫・神戸 元町','Kobe · Motomachi',34.68904301401889,135.1890776200576,'神戸の元町へようこそ。商店街が続き、南京町（中華街）も近くです。','Welcome to Motomachi in Kobe, a long shopping district close to Nankinmachi, the Chinese quarter.','Motomachi shopping arcades, Nankinmachi Chinatown, Kobe beef, Kitano foreigners district and the harbor area (Meriken Park, Port Tower). About 30 minutes from Osaka by train.','kkZjbgbQZbsK1VYc1C6QAg',true,100),
('kanazawa-kenroku','石川・金沢 兼六園','Kanazawa · Kenrokuen Garden',36.56210779579367,136.6626976262752,'金沢の兼六園へようこそ。日本三名園の一つで、季節ごとの景色が楽しめます。','Welcome to Kenrokuen in Kanazawa, counted as one of the three great gardens of Japan, beautiful in every season.','Kenrokuen Garden, Kanazawa Castle Park, 21st Century Museum of Contemporary Art, Omicho Market for seafood. Winter yukitsuri rope-supported pine trees. About 2.5 hours from Tokyo by Hokuriku Shinkansen.','MnQLP_6LQMT5HkqPfr-BcA',true,110),
('kanazawa-higashi','石川・金沢 ひがし茶屋街','Kanazawa · Higashi Chaya District',36.57275038949604,136.6655809556834,'金沢のひがし茶屋街へようこそ。古い茶屋の町並みが残る、石畳の通りです。','Welcome to the Higashi Chaya district in Kanazawa, with preserved old teahouse streets.','Higashi Chaya teahouse district, gold leaf sweets and crafts, Kazue-machi and Nishi Chaya nearby, Omicho Market. Compact and walkable. Narrow streets get busy at midday; early morning is calm.','tLkC03y0a2Nff3AYex3aNA',true,120),
('kurashiki-bikan','岡山・倉敷 美観地区','Okayama · Kurashiki Bikan District',34.59635597415637,133.7725461466362,'倉敷の美観地区へようこそ。白壁の蔵や、柳が並ぶ運河沿いの町並みです。','Welcome to the Bikan Historical Quarter in Kurashiki, with white-walled storehouses and a willow-lined canal.','Bikan Historical Quarter, canal boat rides, Ohara Museum of Art, denim and craft shops. About 20 minutes from Okayama by train. A relaxed half-day town; evenings are quiet after shops close.','AkSj9C-2h05__eSVqkBOTA',true,130),
('hiroshima-peace-park','広島・原爆ドーム','Hiroshima · Atomic Bomb Dome',34.39549744186948,132.4535920961856,'広島の原爆ドームへようこそ。すぐ近くに平和記念公園があります。','Welcome to the Atomic Bomb Dome in Hiroshima. Peace Memorial Park is right next to it.','Peace Memorial Park and Museum, Atomic Bomb Dome, Hiroshima Castle, okonomiyaki Hiroshima style, Miyajima and Itsukushima Shrine are reachable by tram and ferry. Be respectful at memorial sites.','UK9I8gZuBrx0DzOSUJLDIA',true,140),
('miyajima','広島・宮島','Hiroshima · Miyajima',34.29554261065283,132.3204272940036,'宮島へようこそ。海に立つ大鳥居で知られる、厳島神社の島です。','Welcome to Miyajima, the island of Itsukushima Shrine and its famous torii gate standing in the sea.','Itsukushima Shrine and the floating torii (the tide changes how it looks), free-roaming deer, Mt. Misen ropeway, momiji manju and grilled oysters. Ferry from Miyajimaguchi takes about 10 minutes. Tides decide when you can walk up to the torii.','O2ZB5OFlT5jscs_55U5Zlg',true,150),
('sapporo-odori','北海道・札幌 時計台周辺','Hokkaido · Sapporo Clock Tower area',43.06212993371935,141.3533078185712,'札幌へようこそ。ここは時計台の近くで、大通公園は南へ歩いてすぐです。','Welcome to Sapporo. You are near the Clock Tower, and Odori Park is a short walk south.','Sapporo Clock Tower, Odori Park, Sapporo TV Tower, Susukino nightlife, ramen and seafood, Nijo Market, Otaru and Jozankei are day-trip options. Winters are very cold and snowy; check transport conditions.','5VJ4k55aSrVy4ePP1TdW9Q',true,160),
('fukuoka-tenjin','福岡・天神','Fukuoka · Tenjin',33.59098774822968,130.3989574990601,'福岡の天神へようこそ。九州でも指折りの繁華街で、地下街やショッピングビルが並びます。','Welcome to Tenjin in Fukuoka, one of Kyushu''s biggest shopping and dining districts.','Tenjin shopping and underground mall, yatai food stalls along the river in the evening, Hakata ramen and mentaiko, Nakasu and Canal City nearby, Dazaifu Tenmangu is a day trip. The airport is very close to the city center by subway.','I-H-ik_RTk82urI6ZXB42g',true,170),
('dazaifu','福岡・太宰府','Fukuoka · Dazaifu',33.52139218519632,130.5345120031818,'太宰府へようこそ。学問の神様をまつる太宰府天満宮への参道のあたりです。','Welcome to Dazaifu, near the approach to Dazaifu Tenmangu, the shrine of the god of learning.','Dazaifu Tenmangu shrine, umegae mochi sweets on the approach, Kyushu National Museum. About 30 minutes from central Fukuoka by train. Plum blossoms in late winter; very busy at New Year.','D_UeKBRx67erd2EjI0d8Jw',true,180),
('kumamoto-castle','熊本・熊本城','Kumamoto · Kumamoto Castle',32.80631391252409,130.7054145646807,'熊本城へようこそ。石垣の大きな城で、復旧の工事が続く場所もあります。','Welcome to Kumamoto Castle, known for its tall stone walls. Some areas are still being restored.','Kumamoto Castle and its stone walls, Sakura-no-baba Johsaien food street, Suizenji Garden, basashi and karashi renkon. Restoration after the 2016 earthquake continues, so some areas may be closed. The streetcar runs near the castle.','A2-jeXP34B-MGrqF0vdr0w',true,190),
('naha-kokusai-dori','沖縄・那覇 牧志市場','Okinawa · Naha Makishi Market',26.21495936361764,127.6887845996086,'那覇の牧志市場のあたりへようこそ。国際通りのすぐ近くの、屋根のある商店街です。','Welcome to the Makishi Market area in Naha, a covered shopping arcade right next to Kokusai-dori.','Kokusai-dori, Makishi Public Market, Shuri Castle area, Okinawan food such as soki soba and goya champuru, beaches and Churaumi Aquarium need a car or bus. Typhoon season can disrupt transport.','vHQGtjLfI_GyfPE8CAVR-A',true,200)
