-- 2026-11-16: location review. Every point is an official (Google-captured) outdoor panorama with
-- navigation arrows, checked by eye. pano_id pins the exact panorama so the embed does not snap to
-- a nearby indoor photo. fukuoka-nakasu is retired (inside a building); fukuoka-tenjin replaces it.
alter table public.cities add column if not exists pano_id text;

on conflict (id) do update set
  name_ja = excluded.name_ja, name_en = excluded.name_en, lat = excluded.lat, lng = excluded.lng,
  intro_ja = excluded.intro_ja, intro_en = excluded.intro_en, guide_notes = excluded.guide_notes,
  pano_id = excluded.pano_id, active = excluded.active, sort = excluded.sort;

update public.cities set active = false where id = 'fukuoka-nakasu';
